    # Initialize a counter for opening parentheses
    open_count = 0
    # Iterate through each character in the string
    for char in s:
        # If the character is an opening parenthesis, increment the counter
        if char == '(':
            open_count += 1
        # If the character is a closing parenthesis, decrement the counter
        elif char == ')':
            open_count -= 1
        # If at any point the counter is negative, it means there are more closing parentheses than opening ones
        if open_count < 0:
            return False
    # If the counter is zero, all opening parentheses have been matched with closing ones
    return open_count == 0

