def permutation_coefficient(n, k):
    # Base case: if k is 0 or n is 0, the permutation coefficient is 1
    if k == 0 or n == 0:
        return 1
    # Recursive case: permutation coefficient is n! / (k! * (n-k)!)
    else:
        return n! // (k! * (n-k)!)

