def same_order(list1, list2):
    # Convert both lists to sets to remove duplicates and allow for order comparison
    set1 = set(list1)
    set2 = set(list2)

    # Check if the intersection of the two sets is not empty
    if set1.intersection(set2):
        return True
    else:
        return False
